const ROOT=__dirname,PUBLIC=path.join(ROOT,'public'),DB=path.join(ROOT,'data','db.json'),UPLOAD=path.join(PUBLIC,'uploads','products');fs.mkdirSync(UPLOAD,{recursive:true});
const mime={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8','.json':'application/json; charset=utf-8','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.gif':'image/gif','.svg':'image/svg+xml'};
const uid=p=>`${p}-${crypto.randomUUID()}`;
const sessions=new Map();
const SESSION_TTL=12*60*60*1000;
const permissionMatrix={owner:['*'],admin:['shops.manage','catalog.view','catalog.manage','orders.view','orders.manage','telegram.manage','analytics.view','team.manage','integrations.manage','settings.manage'],manager:['catalog.view','orders.view','orders.manage','telegram.manage','analytics.view'],catalog:['catalog.manage'],analyst:['analytics.view','orders.view']};
const userPermissions=role=>permissionMatrix[role]||[];
function bearer(req){return String(req.headers.authorization||'').replace(/^Bearer\s+/i,'').trim()}
function session(req){const token=bearer(req),x=sessions.get(token);if(!x||x.expiresAt<Date.now()){if(token)sessions.delete(token);return null}x.expiresAt=Date.now()+SESSION_TTL;return x}
function hasPermission(user,perm){const list=userPermissions(user?.role);return list.includes('*')||list.includes(perm)}
function requireUser(req,res,perm){const u=session(req);if(!u){json(res,401,{error:'Требуется авторизация'});return null}if(perm&&!hasPermission(u,perm)){json(res,403,{error:'Недостаточно прав доступа'});return null}return u}
function audit(db,user,action,details={}){db.audit||(db.audit=[]);db.audit.push({id:uid('audit'),actor:user?.email||'system',role:user?.role||'system',action,details,createdAt:new Date().toISOString()});if(db.audit.length>2000)db.audit=db.audit.slice(-2000)}const read=()=>JSON.parse(fs.readFileSync(DB,'utf8'));const write=db=>{const t=DB+'.tmp';fs.writeFileSync(t,JSON.stringify(db,null,2));fs.renameSync(t,DB)};
const send=(res,status,data,type='application/json; charset=utf-8')=>{res.writeHead(status,{'content-type':type,'cache-control':'no-store'});res.end(type.startsWith('application/json')?JSON.stringify(data):data)};
const json=(res,s,d)=>send(res,s,d);const body=req=>new Promise((ok,no)=>{let r='';req.on('data',c=>{r+=c;if(r.length>5e6){no(new Error('Слишком большой запрос'));req.destroy()}});req.on('end',()=>{if(!r)return ok({});try{ok(JSON.parse(r))}catch{no(new Error('Некорректный JSON'))}});req.on('error',no)});
function serve(res,file){const f=path.resolve(PUBLIC,file.replace(/^\/+/,''));if(!f.startsWith(PUBLIC)||!fs.existsSync(f)||!fs.statSync(f).isFile())return send(res,404,'Not found','text/plain; charset=utf-8');send(res,200,fs.readFileSync(f),mime[path.extname(f).toLowerCase()]||'application/octet-stream')}
