function parseMultipart(req,max=12*1024*1024){return new Promise((resolve,reject)=>{const ct=req.headers['content-type']||'',m=ct.match(/boundary=(?:"([^"]+)"|([^;]+))/i);if(!m)return reject(new Error('Ожидается multipart/form-data'));const b='--'+(m[1]||m[2]);let size=0,chunks=[];req.on('data',c=>{size+=c.length;if(size>max){reject(new Error('Файл больше 12 МБ'));req.destroy()}else chunks.push(c)});req.on('end',()=>{try{const sections=Buffer.concat(chunks).toString('binary').split(b),out=[];for(const s of sections){const i=s.indexOf('\r\n\r\n');if(i<0)continue;const h=s.slice(0,i);let d=Buffer.from(s.slice(i+4),'binary');if(d.slice(-2).toString()==='\r\n')d=d.slice(0,-2);out.push({name:h.match(/name="([^"]+)"/)?.[1]||'',filename:h.match(/filename="([^"]*)"/)?.[1]||'',contentType:h.match(/Content-Type:\s*([^\r\n]+)/i)?.[1]?.trim()||'',data:d})}resolve(out)}catch(e){reject(e)}});req.on('error',reject)})}

function normalizeImportRow(r={}){const pick=(...keys)=>{for(const k of keys){if(r[k]!==undefined&&r[k]!==null&&String(r[k]).trim()!=='')return r[k]}return''};return{name:pick('name','Название','Наименование','Товар'),sku:pick('sku','SKU','Артикул'),barcode:pick('barcode','Штрихкод','EAN'),brand:pick('brand','Бренд'),supplier:pick('supplier','Поставщик'),cost:pick('cost','Закупочная цена','Себестоимость'),price:pick('price','Цена','Розничная цена'),comparePrice:pick('comparePrice','Старая цена','Цена до скидки'),stock:pick('stock','Остаток','Количество'),lowStock:pick('lowStock','Порог остатка'),active:pick('active','Опубликован','Активен'),tags:pick('tags','Теги'),description:pick('description','Описание'),image:pick('image','Изображение','Фото'),categoryId:pick('categoryId','ID категории'),category:pick('category','Категория'),subcategory:pick('subcategory','Подкатегория'),variant:pick('variant','Вариация','Вкус'),variantPrice:pick('variantPrice','Цена вариации'),variantStock:pick('variantStock','Остаток вариации')}}
function importRows(db,shopId,rows){let created=0,updated=0,errors=[];for(let i=0;i<rows.length;i++){const r=normalizeImportRow(rows[i]||{});if(!r.name||r.price===''){errors.push({row:i+2,error:'Название и цена обязательны'});continue}let x=db.products.find(v=>v.shopId===shopId&&r.sku&&v.sku===String(r.sku).trim());const data={shopId,categoryId:String(r.categoryId||''),name:String(r.name).trim(),sku:String(r.sku||uid('SKU')).trim(),barcode:String(r.barcode||'').trim(),brand:String(r.brand||'').trim(),supplier:String(r.supplier||'').trim(),cost:Number(r.cost||0),price:Number(r.price||0),comparePrice:Number(r.comparePrice||0),stock:Number(r.stock||0),lowStock:Number(r.lowStock||5),description:String(r.description||''),tags:Array.isArray(r.tags)?r.tags:String(r.tags||'').split(/[|,;]/).map(x=>x.trim()).filter(Boolean),active:!['false','0','нет','no'].includes(String(r.active??'true').toLowerCase()),image:r.image||'https://placehold.co/700x700?text=GtStore',variants:[]};if(!Number.isFinite(data.price)){errors.push({row:i+2,error:'Некорректная цена'});continue}if(x){Object.assign(x,data,{updatedAt:new Date().toISOString()});updated++}else{db.products.push({...data,id:uid('p'),gallery:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});created++}}return{created,updated,errors}}

